#!/usr/bin/env bash
# Run the declarative pipeline once. Streaming tables only process files that arrived since the last run.
set -euo pipefail
cd "$(dirname "$0")/.."
ROOT="$PWD"
export SPARK_CONF_DIR="$ROOT/conf" LANDING_PATH="$ROOT/data/landing"
# the spec needs an absolute storage URI, so render it for this checkout
cat > pipelines/spark-pipeline.yml <<YML
# Generated by scripts/run_pipeline.sh. Spark Declarative Pipelines spec (open-source core of
# Databricks Lakeflow Declarative Pipelines); see databricks/ for the Databricks deployment.
name: revenue_quality_pipeline
storage: file://$ROOT/data/pipeline-storage
database: revenue
configuration:
  spark.sql.sources.default: delta
libraries:
  - glob:
      include: transformations/**
YML
cd pipelines && uv run spark-pipelines run "$@"
